head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
scwin.vScrenID = "ULDSTF05317.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vAcptNo = "";
scwin.vIsurCd = "";
scwin.vOpenTyp = "";
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_140; //종목명변경
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_bf_read_sync = function() {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_BF_INFO + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_recv_read_sync = function(row) {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_RECV_READ + "&ACPT_NO=" + scwin.vAcptNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_read_sync = function(row) {
    var url = "/Listing.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchIsuNmChgList&DIV_IDX=" + DIV_IDX_ISU_NM_HIST_READ + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_CheckForm = function() {
    scwin.fn_removeEnter();
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD)) {
        $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }


    //(3264)2010.12.27 ETF 종목명 변경 	
    if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
        if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM) != "") {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_NM, 80, "한글종목명")) return false;
        }
        if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_ABBRV) != "") {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_ABBRV, 40, "한글종목약명")) return false;
        }
        if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM) != "") {
            if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
        if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_ABBRV) != "") {
            if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        }
        if (scwin.vSYMBL_INPUT_CD == '1') {
            if (scwin.vSecuGrpId == SECUGRP_ID_EF || scwin.vSecuGrpId == SECUGRP_ID_FE) {
                if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL) != "") {
                    if (!$c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISU_CD), dts_Symbl)) {
                        $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                        return false;
                    }
                }
            }
        }
    } else {
        if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM) == "") {
            $c.win.alert("[한글종목명]을 입력하세요.");
            txb_AFCHG_ISU_KOR_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_NM, 80, "한글종목명")) return false;
        if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_ABBRV) == "") {
            $c.win.alert("[한글종목약명]을 입력하세요.");
            txb_AFCHG_ISU_KOR_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_KOR_ABBRV, 40, "한글종목약명")) return false;
        if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM) == "") {
            $c.win.alert("[영문종목명]을 입력하세요.");
            edt_AFCHG_ISU_ENG_NM.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_ABBRV) == "") {
            $c.win.alert("[영문종목약명]을 입력하세요.");
            edt_AFCHG_ISU_ENG_ABBRV.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(edt_AFCHG_ISU_ENG_ABBRV, 40, "영문종목약명")) return false;
        if (scwin.vSYMBL_INPUT_CD == '1') {
            if (scwin.vSecuGrpId == SECUGRP_ID_EF || scwin.vSecuGrpId == SECUGRP_ID_FE) {
                if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL) == "") {
                    $c.win.alert("[영문종목심볼]을 입력하세요.");
                    edt_AFCHG_ISU_ENG_SYMBL.focus();
                    return false;
                }
                if (!$c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISU_CD), dts_Symbl)) {
                    $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                    return false;
                }
            }
        }
    }

    /* 2009-04-24 종목명변경으로 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISU_CD), $c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD), scwin.vBzProcsNo, LIST_BZ_TP_CD_140)) {
        return false;
    }
    return true;
};


//(3264) 2010.12.27 ETF 종목명 변경
scwin.fn_checkSave = function() {
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM) == "" || $c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM) == "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_KOR_NM", $c.stf.getObjectValue(txb_BFCHG_ISU_KOR_NM));
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_ABBRV) == "" || $c.stf.getObjectValue(txb_AFCHG_ISU_KOR_ABBRV) == "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_KOR_ABBRV", $c.stf.getObjectValue(txb_BFCHG_ISU_KOR_ABBRV));
    }
    if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM) == "" || $c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM) == "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_ENG_NM", $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_NM));
    }
    if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_ABBRV) == "" || $c.stf.getObjectValue(edt_AFCHG_ISU_ENG_ABBRV) == "-") {
        dts_Isu.setCellData(1, "AFCHG_ISU_ENG_ABBRV", $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_ABBRV));
    }
    if (scwin.vSYMBL_INPUT_CD == '1') {
        if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL) == "" || $c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL) == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_ENG_SYMBL", $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_SYMBL));
        }
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo == "") {
            scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

            //(3264) 2010.12.27 ETF 종목명 변경
            if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
                scwin.fn_checkSave();
            }
            //-

            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;

        //(3264) 2010.12.27 ETF 종목명 변경
        if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
            scwin.fn_checkSave();
        }
        //-

        scwin.fn_trs(TRS_IDX_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TRS_IDX_DELETE);
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/Listing.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveChgList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",ACPT_NO=" + scwin.vAcptNo + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=1" + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",DIV_IDX[0]=" + DIV_IDX_ISUNM_CHG;
    trs_Save.Post();
};
scwin.fn_RecvtIsuDel = function() {
    if (scwin.vAcptNo == "") {
        $c.win.alert('변경예정내역에서 대상종목을 선택하세요');
        return;
    }
    scwin.vAcptNo = ''; //biz단에서 체크하기때문에 초기화 필수 .

    scwin.fn_delete(TRS_IDX_DELETE);
};
scwin.fn_getIsuNmDisclsCtnt = function() {
    var vCtnt = "";
    if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
        vCtnt += "1. 변경내역(변경전 → 변경후)";
        vCtnt += "\r\n";
        vCtnt += "    - 한글종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + $c.stf.getObjectValue(txb_BFCHG_ISU_KOR_NM) + " → " + $c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM);
        vCtnt += "\r\n";
        vCtnt += "    - 영문종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_NM) + " → " + $c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM);
        vCtnt += "\r\n";
        vCtnt += "2. 변경상장일: " + scwin.dateForm($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD));
        vCtnt += "\r\n";
        vCtnt += "3. 변경사유: 신탁계약 변경에 따른 종목명 변경";
        vCtnt += "\r\n";
        vCtnt += "4. 운용사(위탁사): " + dts_Isu.getCellData(1, "TRST_COM_NM");
        vCtnt += "\r\n";
    } else {
        vCtnt += "1. 변경내역(변경전 → 변경후)";
        vCtnt += "\r\n";
        vCtnt += "    - 한글종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + $c.stf.getObjectValue(txb_BFCHG_ISU_KOR_NM) + " → " + $c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM);
        vCtnt += "\r\n";
        vCtnt += "    - 영문종목명";
        vCtnt += "\r\n";
        vCtnt += "         o " + $c.stf.getObjectValue(txb_BFCHG_ISU_ENG_NM) + " → " + $c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM);
        vCtnt += "\r\n";
        vCtnt += "2. 변경일자: " + scwin.dateForm($c.stf.getObjectValue(edt_MKTACT_ENFORCE_DD));
        vCtnt += "\r\n";
        vCtnt += "3. 변경사유: ★★★★★★★★★★★★";
        vCtnt += "\r\n";
    }
    return vCtnt;
};
scwin.dateForm = function(pStr) {
    var str = "";
    if (pStr == "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};
scwin.fn_dscl = async function() {
    if (scwin.vBzProcsNo == '') {
        $c.win.alert("공시안내문 생성 처리할 대상자료가 선택되지 않았거나, 없습니다.");
    }
    if ($c.cp.isModified(dts_Isu)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68959"; //68926:기타안내사항 -> 689599:종목명 변경) 으로 서식코드변경
        arr[1] = scwin.vBzProcsNo;
        arr[2] = scwin.vIsurCd;
        arr[3] = js_market;
        arr[4] = scwin.fn_getIsuNmDisclsCtnt();
        if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
            //코스콤 전송시 접수에서 제목에 종목명을 셋팅해서 처리에서는 제외함.
            arr[5] = '';
        } else {
            arr[5] = $c.stf.getObjectValue(txb_ISU_NM);
        }

        //CopyDataSet( dts_Isu , param_dts_isu) ;
        //CopyDataSet(dts_Isu , param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ISU_CD", txb_ISU_CD.getValue());
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_all_list_sync;
    fr_fn_list_sync();
};
scwin.fn_setComponentSymbl = function() {
    if (scwin.vSYMBL_INPUT_CD == '1') {
        if (scwin.vSecuGrpId == SECUGRP_ID_EF || scwin.vSecuGrpId == SECUGRP_ID_FE) {
            $c.stf.showObj(panel_SYMBL, true);
        } else {
            $c.stf.showObj(panel_SYMBL, false);
        }
    } else if (scwin.vSYMBL_INPUT_CD == '2') {
        $c.stf.showObj(panel_SYMBL, false);
    }
};



/*
 * 종목명 개행문자 제거를 위해 변수에 담았다가 다시 셋팅
 * getObjectValue 하면서 제거되는듯
 */
scwin.fn_removeEnter = function() {
    $c.stf.setObjectValue(txb_AFCHG_ISU_KOR_NM, $c.ut.trim($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_NM)));
    $c.stf.setObjectValue(txb_AFCHG_ISU_KOR_ABBRV, $c.ut.trim($c.stf.getObjectValue(txb_AFCHG_ISU_KOR_ABBRV)));
    $c.stf.setObjectValue(edt_AFCHG_ISU_ENG_NM, $c.ut.trim($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_NM)));
    $c.stf.setObjectValue(edt_AFCHG_ISU_ENG_ABBRV, $c.ut.trim($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_ABBRV)));
    $c.stf.setObjectValue(edt_AFCHG_ISU_ENG_SYMBL, $c.ut.trim($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL)));
};
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    popUpCalendar2(edt_MKTACT_ENFORCE_DD);
};
scwin.img_ISU_ENG_SYMBL_onclick = function() {
    if ($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL) == "") {
        $c.win.alert("[영문종목심볼]을 입력하세요.");
        edt_AFCHG_ISU_ENG_SYMBL.focus();
        return false;
    } else {
        $c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(edt_AFCHG_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISU_CD), dts_Symbl);
        if (!$c.ut.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
            $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_RecvIsuDel_onclick = function() {
    scwin.fn_RecvtIsuDel();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (scwin.vOpenTyp == "N" || (scwin.vOpenTyp == "R")) {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_MKTACT_ENFORCE_DD, false);
        $c.stf.setButtonSetWithDate2(dts_Isu.getCellData(1, "DISCLS_YN"));
    }
    if (scwin.vOpenTyp == "R") {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel.gif";
        btn_RecvIsuDel.setDisabled(false);
    } else {
        btn_RecvIsuDel.src = "../img/btn_RcvdocDel_d.gif";
        btn_RecvIsuDel.setDisabled(true);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.vOpenTyp = "H";
        scwin.fn_read_sync();
    }
};
scwin.gform_onload = function() {
    //var parentWin = fn_GetProvider();
    var parentWin = $c.frame.path("../");
    //alert('[parentWin]'+parentWin);
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.vAcptNo = parentWin.scwin.vAcptNo;
    scwin.vIsurCd = parentWin.scwin.vIsurCd;
    scwin.vOpenTyp = parentWin.scwin.vOpenTyp;
    scwin.vSecuGrpId = parentWin.fr_SecuGrpId;
    $c.stf.setObjectValue(txb_ISU_CD, $c.stf.getObjectValue(parentWin.txb_ISU_CD));
    $c.stf.setObjectValue(txb_ISU_NM, $c.stf.getObjectValue(parentWin.txb_ISU_NM));
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.vSYMBL_INPUT_CD = js_market;
    scwin.fn_setComponentSymbl();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성s
    //buttonSet.setDrftInfo( btn_Drft, fn_drft );			// 기안


    //2010.12.30 ETF 종목명 변경
    if (scwin.vOpenTyp == "R") {
        scwin.fn_recv_read_sync();
        if (dts_Isu.getCellData(1, "AFCHG_ISU_KOR_NM") == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_KOR_NM", "");
        }
        if (dts_Isu.getCellData(1, "AFCHG_ISU_KOR_ABBRV") == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_KOR_ABBRV", "");
        }
        if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_NM") == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_ENG_NM", "");
        }
        if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_ABBRV") == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_ENG_ABBRV", "");
        }
        if (dts_Isu.getCellData(1, "AFCHG_ISU_ENG_SYMBL") == "-") {
            dts_Isu.setCellData(1, "AFCHG_ISU_ENG_SYMBL", "");
        }
    } else if (scwin.vOpenTyp == "H") {
        scwin.fn_read_sync();
    } else if (scwin.vOpenTyp == "N") {
        scwin.fn_bf_read_sync();
    }
    if (scwin.vSecuGrpId == SECUGRP_ID_EF) {
        txb_memo.setDisabled(false);
        txb_memo.setValue("* '변경후' 종목명에 값이 없을 경우 '변경전' 종목명 값으로 저장됩니다.");
    } else {
        txb_memo.setDisabled(true);
    }
    buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, scwin.vSecuGrpId, scwin.vIsurCd, js_dep_cd);
};
